 "content": "def transform(grid):
    """Extend the center row and column of each solid 3x3 color block."""
    h, w = len(grid), len(grid[0])
    blocks = []
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color == 0:
                continue
            if all(grid[rr][cc] == color
                   for rr in range(r, r + 3)
                   for cc in range(c, c + 3)):
                # Keep only the top-left occurrence of a detected 3x3 block.
                if r > 0 and c + 2 < w and all(grid[r - 1][cc] == color for cc in range(c, c + 3)):
                    continue
                if c > 0 and r + 2 < h and all(grid[rr][c - 1] == color for rr in range(r, r + 3)):
                    continue
                blocks.append((r + 1, c + 1, color))

    out = [row[:] for row in grid]
    rays = {}
    for r, c, color in blocks:
        for cc in range(w):
            rays.setdefault((r, cc), set()).add(color)
        for rr in range(h):
            rays.setdefault((rr, c), set()).add(color)
    for (r, c), colors in rays.items():
        out[r][c] = next(iter(colors)) if len(colors) == 1 else 0
    return out

if __name__ == '__main__':
    import sys, json
    print(json.dumps(transform(json.load(sys.stdin))))
